class Heap {
  constructor(cmp) {
    this.a = []
    this.cmp = cmp
  }
  get size() {
    return this.a.length
  }
  peek() {
    return this.a[0]
  }
  push(x) {
    const a = this.a
    a.push(x)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (this.cmp(a[i], a[p]) >= 0) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop() {
    const a = this.a
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l
        if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function narrowestRange(lists) {
  const heap = new Heap((a, b) => a[0] - b[0] || a[1] - b[1])
  let high = -Infinity
  lists.forEach((list, i) => {
    heap.push([list[0], i, 0])
    high = Math.max(high, list[0])
  })
  let best = [heap.peek()[0], high]
  for (;;) {
    const [low, i, j] = heap.pop()
    if (high - low < best[1] - best[0]) best = [low, high]
    if (j + 1 === lists[i].length) return best
    const next = lists[i][j + 1]
    high = Math.max(high, next)
    heap.push([next, i, j + 1])
  }
}
